```bash
cd /home/vscode/nullness-benchmarks/glide && sed -i '140,144s/onLoadFailed(@NonNull Exception e) {
    LoadData<?> local = loadData;
    if (local != null) {
      cb.onDataFetcherFailed(currentKey, e, local.fetcher, DataSource.RESOURCE_DISK_CACHE);
    }/onLoadFailed(@NonNull Exception e) {
    LoadData<?> local = loadData;
    if (local == null) {
      return;
    }
    cb.onDataFetcherFailed(currentKey, e, local.fetcher, DataSource.RESOURCE_DISK_CACHE);/g' library/src/main/java/com/bumptech/glide/load/engine/ResourceCacheGenerator.java && ./gradlew library:compileDebugJavaWithJavac -x test -q > new_build_output.log 2>&1 && grep -n "ResourceCacheGenerator" new_build_output.log || tail -n 40 new_build_output.log
```

